insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('ferrugem-asiatica', 'fungo', 'Ferrugem asiática', 'Phakopsora pachyrhizi', array['Pontinhos escuros na face de cima da folha, começando pelas folhas de baixo','Na face de baixo, pequenas saliências (urédias) que soltam um pó claro','Folhas amarelam e caem cedo; grãos ficam leves']::text[], 'Começa no terço inferior da planta com lesões pequenas, de cor castanha a cinza-esverdeada, vistas melhor contra a luz. Na face inferior aparecem urédias em forma de vulcão que liberam esporos. Com a doença avançando, as lesões se juntam, a folha amarela e cai. Desfolha antes do enchimento de grãos é o que mais derruba a produtividade.', 'Fungo que só sobrevive em planta viva (biotrófico), por isso o vazio sanitário funciona. Os esporos viajam com o vento por longas distâncias. Folha molhada por 6 horas ou mais e temperatura entre 18 e 28 °C favorecem a infecção.', array['Respeitar o vazio sanitário e o calendário de semeadura da sua região','Semear no início da janela recomendada e preferir cultivares de ciclo precoce','Eliminar soja guaxa (tiguera) na entressafra','Acompanhar os boletins do Consórcio Antiferrugem e monitorar a partir do fechamento das entrelinhas']::text[], 'Pontinhos escuros na face de cima da folha, começando pelas folhas de baixo Na face de baixo, pequenas saliências (urédias) que soltam um pó claro Folhas amarelam e caem cedo; grãos ficam leves Começa no terço inferior da planta com lesões pequenas, de cor castanha a cinza-esverdeada, vistas melhor contra a luz. Na face inferior aparecem urédias em forma de vulcão que liberam esporos. Com a doença avançando, as lesões se juntam, a folha amarela e cai. Desfolha antes do enchimento de grãos é o que mais derruba a produtividade.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)','MAPA — Agrofit (consulta de produtos registrados)']::text[], 'published', 32)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
    summary = excluded.summary, symptoms = excluded.symptoms, cause = excluded.cause, preventive_measures = excluded.preventive_measures,
    visual_cues = excluded.visual_cues, sources = excluded.sources, placeholder_hue = excluded.placeholder_hue;
