insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'biologico', 'Há produtos biológicos registrados para a doença; funcionam como complemento ao manejo, não como substitutos dos fungicidas em alta pressão.', null, null, null, 1 from problems where slug = 'ferrugem-asiatica';
insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'quimico', 'Aplicação preventiva ou no início dos sintomas, sempre em mistura e com rotação de modos de ação para evitar resistência. Multissítios ajudam a proteger as moléculas sítio-específicas.', 'Triazóis, estrobilurinas, carboxamidas e multissítios', 'FRAC 3, 11, 7 e M', 'https://agrofit.agricultura.gov.br/agrofit_cons/principal_agrofit_cons', 2 from problems where slug = 'ferrugem-asiatica';
insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('mancha-alvo', 'fungo', 'Mancha-alvo', 'Corynespora cassiicola', array['Manchas arredondadas com anéis concêntricos, como um alvo','Halo amarelado em volta da mancha','Pode atingir folhas, hastes e vagens']::text[], 'Lesões que começam como pontos pardos e crescem em círculos com anéis mais escuros e mais claros alternados, geralmente com um halo amarelo. Em ataques fortes há desfolha e manchas também em hastes e vagens.', 'O fungo sobrevive em restos de cultura e em sementes, e tem muitos hospedeiros. Alta umidade e chuvas frequentes favorecem. A monocultura de soja aumenta a quantidade de inóculo na área.', array['Rotação de culturas com gramíneas','Cultivares menos suscetíveis','Sementes sadias e tratadas']::text[], 'Manchas arredondadas com anéis concêntricos, como um alvo Halo amarelado em volta da mancha Pode atingir folhas, hastes e vagens Lesões que começam como pontos pardos e crescem em círculos com anéis mais escuros e mais claros alternados, geralmente com um halo amarelo. Em ataques fortes há desfolha e manchas também em hastes e vagens.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 24)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
