insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'quimico', 'Fungicidas em mistura, priorizando moléculas com boa eficiência para mancha-alvo na sua região; há relatos de menor sensibilidade a alguns grupos.', 'Carboxamidas, multissítios e triazóis', 'FRAC 7, M e 3', 'https://agrofit.agricultura.gov.br/agrofit_cons/principal_agrofit_cons', 1 from problems where slug = 'mancha-alvo';
insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('antracnose', 'fungo', 'Antracnose', 'Colletotrichum truncatum', array['Nervuras escurecidas na face de baixo das folhas','Vagens com manchas escuras e deformadas','Pode causar apodrecimento de vagens e queda']::text[], 'Na folha, as nervuras ficam escuras e a folha pode enrolar. Nas hastes e vagens aparecem manchas escuras, às vezes com pontinhos pretos (estruturas do fungo). Vagens atacadas podem ficar chochas ou retorcidas.', 'Transmitido principalmente por semente e restos de cultura. Calor com chuva prolongada e lavouras muito adensadas favorecem.', array['Semente de boa qualidade e tratada','Espaçamento e população adequados para arejar a lavoura','Rotação de culturas']::text[], 'Nervuras escurecidas na face de baixo das folhas Vagens com manchas escuras e deformadas Pode causar apodrecimento de vagens e queda Na folha, as nervuras ficam escuras e a folha pode enrolar. Nas hastes e vagens aparecem manchas escuras, às vezes com pontinhos pretos (estruturas do fungo). Vagens atacadas podem ficar chochas ou retorcidas.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 18)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
