    visual_cues = excluded.visual_cues, sources = excluded.sources, placeholder_hue = excluded.placeholder_hue;
insert into problem_crops (problem_id, crop_id, stages) select p.id, c.id, array['R3','R5']::text[] from problems p, crops c where p.slug = 'antracnose' and c.slug = 'soja'
