insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'quimico', 'Tratamento de sementes e fungicidas foliares nas fases reprodutivas quando há histórico na área.', 'Benzimidazóis no tratamento de sementes; triazóis e estrobilurinas na parte aérea', 'FRAC 1, 3 e 11', 'https://agrofit.agricultura.gov.br/agrofit_cons/principal_agrofit_cons', 1 from problems where slug = 'antracnose';
insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('oidio', 'fungo', 'Oídio', 'Erysiphe diffusa', array['Pó branco acinzentado sobre folhas e hastes','Aparece primeiro na face de cima da folha','Mais comum em tempo seco e ameno']::text[], 'Camada fina de aspecto empoeirado, branca a cinza, que pode cobrir toda a folha. Folhas muito atacadas ficam amareladas e caem antes do tempo.', 'Favorecido por temperaturas amenas (entre 18 e 24 °C) e baixa umidade relativa. Chuva forte lava os esporos e diminui a doença.', array['Cultivares resistentes','Monitorar em períodos secos e amenos']::text[], 'Pó branco acinzentado sobre folhas e hastes Aparece primeiro na face de cima da folha Mais comum em tempo seco e ameno Camada fina de aspecto empoeirado, branca a cinza, que pode cobrir toda a folha. Folhas muito atacadas ficam amareladas e caem antes do tempo.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 60)
