insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('mofo-branco', 'fungo', 'Mofo-branco', 'Sclerotinia sclerotiorum', array['Mancha encharcada na haste que vira um mofo branco parecido com algodão','Corpos pretos e duros (escleródios) dentro e fora da haste','Plantas murcham e secam em reboleiras']::text[], 'Lesões úmidas na haste, geralmente na altura das flores, que se cobrem de micélio branco. Depois surgem escleródios pretos, parecidos com fezes de rato. A planta murcha acima da lesão.', 'Os escleródios sobrevivem anos no solo. Na floração, com frio e umidade, eles germinam e soltam esporos que infectam as flores. Regiões altas e frescas têm mais problema.', array['Semente livre de escleródios','Palhada de gramíneas (cobertura de solo) para dificultar a germinação dos escleródios','Evitar trazer máquinas de áreas infestadas sem limpeza']::text[], 'Mancha encharcada na haste que vira um mofo branco parecido com algodão Corpos pretos e duros (escleródios) dentro e fora da haste Plantas murcham e secam em reboleiras Lesões úmidas na haste, geralmente na altura das flores, que se cobrem de micélio branco. Depois surgem escleródios pretos, parecidos com fezes de rato. A planta murcha acima da lesão.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 210)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
