insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('crestamento-bacteriano', 'bacteria', 'Crestamento bacteriano', 'Pseudomonas savastanoi pv. glycinea', array['Manchas pequenas e angulosas, de aspecto encharcado','Centro escurece e fica com halo amarelo','Partes da folha rasgam e caem com o vento']::text[], 'Pontos encharcados delimitados pelas nervuras, que ficam pardos a pretos com halo amarelo-esverdeado. As lesões secam e o tecido se rompe, deixando a folha rasgada.', 'Bactéria transmitida por semente e espalhada por chuva com vento. Favorecida por tempo fresco e chuvoso no início do ciclo.', array['Semente sadia','Cultivares resistentes','Evitar trânsito na lavoura molhada']::text[], 'Manchas pequenas e angulosas, de aspecto encharcado Centro escurece e fica com halo amarelo Partes da folha rasgam e caem com o vento Pontos encharcados delimitados pelas nervuras, que ficam pardos a pretos com halo amarelo-esverdeado. As lesões secam e o tecido se rompe, deixando a folha rasgada.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 90)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
    summary = excluded.summary, symptoms = excluded.symptoms, cause = excluded.cause, preventive_measures = excluded.preventive_measures,
    visual_cues = excluded.visual_cues, sources = excluded.sources, placeholder_hue = excluded.placeholder_hue;
