insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('percevejo-marrom', 'inseto', 'Percevejo-marrom', 'Euschistus heros', array['Inseto marrom com dois espinhos laterais no ''ombro''','Suga vagens e grãos, deixando grãos chochos e manchados','Pode causar retenção foliar (a ''soja louca'')']::text[], 'O dano não aparece na folha: está nos grãos, que ficam enrugados, menores e com pontinhos escuros onde o inseto picou. Lavouras com muito percevejo podem não completar a maturação e ficar verdes na colheita.', 'Ataca principalmente do início da formação das vagens (R3) até a maturação (R7). Passa a entressafra escondido sob a palhada.', array['Monitorar com pano de batida a partir de R3','Decidir a aplicação pelo nível de ação, não pelo calendário']::text[], 'Inseto marrom com dois espinhos laterais no ''ombro'' Suga vagens e grãos, deixando grãos chochos e manchados Pode causar retenção foliar (a ''soja louca'') O dano não aparece na folha: está nos grãos, que ficam enrugados, menores e com pontinhos escuros onde o inseto picou. Lavouras com muito percevejo podem não completar a maturação e ficar verdes na colheita.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)','MAPA — Agrofit (consulta de produtos registrados)']::text[], 'published', 28)
