insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'biologico', 'Parasitoides de ovos como Telenomus podisi podem ser liberados; preservar os inimigos naturais evitando aplicações desnecessárias.', null, null, null, 1 from problems where slug = 'percevejo-marrom';
insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'quimico', 'Aplicar só quando o nível de ação for atingido, alternando grupos químicos.', 'Neonicotinoides, piretroides e organofosforados', 'IRAC 4A, 3A e 1B', 'https://agrofit.agricultura.gov.br/agrofit_cons/principal_agrofit_cons', 2 from problems where slug = 'percevejo-marrom';
insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('lagarta-da-soja', 'inseto', 'Lagarta-da-soja', 'Anticarsia gemmatalis', array['Lagarta verde (às vezes escura) com listras claras no dorso','Come a folha inteira, deixando só as nervuras','Quando incomodada, se debate com força']::text[], 'Desfolha de cima para baixo, com folhas comidas inclusive nas nervuras mais finas em ataques fortes. Lagartas grandes comem muito mais que as pequenas, por isso o monitoramento cedo é importante.', 'Ocorre da fase vegetativa até o enchimento de grãos. Mariposas põem ovos nas folhas e a população cresce rápido em tempo quente.', array['Monitorar com pano de batida','Preservar inimigos naturais']::text[], 'Lagarta verde (às vezes escura) com listras claras no dorso Come a folha inteira, deixando só as nervuras Quando incomodada, se debate com força Desfolha de cima para baixo, com folhas comidas inclusive nas nervuras mais finas em ataques fortes. Lagartas grandes comem muito mais que as pequenas, por isso o monitoramento cedo é importante.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 100)
