insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'quimico', 'Inseticidas seletivos, que poupam inimigos naturais, quando o nível de ação for atingido.', 'Reguladores de crescimento e diamidas', 'IRAC 15 e 28', 'https://agrofit.agricultura.gov.br/agrofit_cons/principal_agrofit_cons', 2 from problems where slug = 'lagarta-da-soja';
insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('lagarta-falsa-medideira', 'inseto', 'Lagarta-falsa-medideira', 'Chrysodeixis includens', array['Lagarta verde-clara que anda ''medindo palmo'', arqueando o corpo','Come a folha mas deixa as nervuras, que ficam rendilhadas','Fica no terço médio e inferior, mais difícil de atingir']::text[], 'Folhas com aspecto de renda, já que as nervuras ficam. Ataque concentrado no meio e embaixo da planta, onde a calda de pulverização chega com mais dificuldade.', 'Favorecida por tempo quente e seco e por aplicações de produtos que matam os inimigos naturais.', array['Monitoramento no terço médio e inferior','Evitar aplicações desnecessárias']::text[], 'Lagarta verde-clara que anda ''medindo palmo'', arqueando o corpo Come a folha mas deixa as nervuras, que ficam rendilhadas Fica no terço médio e inferior, mais difícil de atingir Folhas com aspecto de renda, já que as nervuras ficam. Ataque concentrado no meio e embaixo da planta, onde a calda de pulverização chega com mais dificuldade.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 80)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
    summary = excluded.summary, symptoms = excluded.symptoms, cause = excluded.cause, preventive_measures = excluded.preventive_measures,
    visual_cues = excluded.visual_cues, sources = excluded.sources, placeholder_hue = excluded.placeholder_hue;
insert into problem_crops (problem_id, crop_id, stages) select p.id, c.id, array['R1','R3','R5']::text[] from problems p, crops c where p.slug = 'lagarta-falsa-medideira' and c.slug = 'soja'
  on conflict (problem_id, crop_id) do update set stages = excluded.stages;
delete from treatments where problem_id = (select id from problems where slug = 'lagarta-falsa-medideira');
insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'cultural', 'Mesmos níveis de ação da lagarta-da-soja; atenção à tecnologia de aplicação para atingir o meio da planta.', null, null, null, 0 from problems where slug = 'lagarta-falsa-medideira';
insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'biologico', 'Baculovírus específico e Bacillus thuringiensis, de preferência em lagartas pequenas.', null, null, null, 1 from problems where slug = 'lagarta-falsa-medideira';
insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'quimico', 'Grupos com boa eficiência para essa espécie, alternando modos de ação.', 'Diamidas e espinosinas', 'IRAC 28 e 5', 'https://agrofit.agricultura.gov.br/agrofit_cons/principal_agrofit_cons', 2 from problems where slug = 'lagarta-falsa-medideira';
insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('mosca-branca', 'inseto', 'Mosca-branca', 'Bemisia tabaci', array['Insetos brancos pequenos que voam quando a planta é mexida','Ninfas imóveis na face de baixo da folha','Fumagina: camada preta sobre as folhas']::text[], 'Folhas com pontos amarelados e, em ataques fortes, cobertas por fumagina, um fungo preto que cresce sobre o melado que o inseto solta. Pode transmitir vírus.', 'Favorecida por tempo quente e seco e por plantios escalonados de culturas hospedeiras.', array['Eliminar plantas hospedeiras na entressafra','Monitorar a face inferior das folhas']::text[], 'Insetos brancos pequenos que voam quando a planta é mexida Ninfas imóveis na face de baixo da folha Fumagina: camada preta sobre as folhas Folhas com pontos amarelados e, em ataques fortes, cobertas por fumagina, um fungo preto que cresce sobre o melado que o inseto solta. Pode transmitir vírus.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 55)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
    summary = excluded.summary, symptoms = excluded.symptoms, cause = excluded.cause, preventive_measures = excluded.preventive_measures,
    visual_cues = excluded.visual_cues, sources = excluded.sources, placeholder_hue = excluded.placeholder_hue;
insert into problem_crops (problem_id, crop_id, stages) select p.id, c.id, array['V6','R1','R5']::text[] from problems p, crops c where p.slug = 'mosca-branca' and c.slug = 'soja'
  on conflict (problem_id, crop_id) do update set stages = excluded.stages;
