insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'biologico', 'Fungos entomopatogênicos, como Beauveria bassiana e Cordyceps fumosorosea, ajudam no manejo.', null, null, null, 0 from problems where slug = 'mosca-branca';
insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'quimico', 'Alternar grupos e focar nas ninfas; a mosca-branca cria resistência rápido.', 'Reguladores de crescimento, neonicotinoides e cetoenóis', 'IRAC 16, 4A e 23', 'https://agrofit.agricultura.gov.br/agrofit_cons/principal_agrofit_cons', 1 from problems where slug = 'mosca-branca';
insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('acaro-rajado', 'acaro', 'Ácaro-rajado', 'Tetranychus urticae', array['Pontinhos amarelados ou bronzeados na folha','Teias finas na face de baixo','Surtos em veranicos (períodos secos)']::text[], 'A folha perde o verde por pontos e depois fica bronzeada ou avermelhada. Com lupa, vê-se os ácaros e as teias na face inferior. Ataque começa em reboleiras e na borda da lavoura.', 'Explode em estiagens e quando inimigos naturais foram mortos por aplicações de amplo espectro.', array['Monitorar bordas em períodos secos','Evitar inseticidas de amplo espectro sem necessidade']::text[], 'Pontinhos amarelados ou bronzeados na folha Teias finas na face de baixo Surtos em veranicos (períodos secos) A folha perde o verde por pontos e depois fica bronzeada ou avermelhada. Com lupa, vê-se os ácaros e as teias na face inferior. Ataque começa em reboleiras e na borda da lavoura.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 12)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
    summary = excluded.summary, symptoms = excluded.symptoms, cause = excluded.cause, preventive_measures = excluded.preventive_measures,
    visual_cues = excluded.visual_cues, sources = excluded.sources, placeholder_hue = excluded.placeholder_hue;
