insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'quimico', 'Acaricidas específicos registrados para a cultura; inseticidas comuns não controlam ácaros.', 'Acaricidas específicos', 'IRAC 6, 20 ou 23', 'https://agrofit.agricultura.gov.br/agrofit_cons/principal_agrofit_cons', 1 from problems where slug = 'acaro-rajado';
insert into problems (slug, agent_type, common_name, scientific_name, summary, symptoms, cause, preventive_measures, visual_cues, sources, status, placeholder_hue)
  values ('deficiencia-de-potassio', 'deficiencia', 'Deficiência de potássio', 'K', array['Amarelecimento nas bordas das folhas mais velhas','Bordas secam e ficam pardas, enquanto o centro continua verde','Plantas com haste fina e grãos menores']::text[], 'Começa nas folhas de baixo porque o potássio se move para as folhas novas. As margens amarelam e depois necrosam. Em casos fortes, a maturação atrasa e os grãos ficam enrugados.', 'Solo pobre em potássio, adubação insuficiente para a produtividade esperada ou solos arenosos com perda por lixiviação.', array['Análise de solo antes do plantio','Adubação de manutenção conforme a recomendação regional']::text[], 'Amarelecimento nas bordas das folhas mais velhas Bordas secam e ficam pardas, enquanto o centro continua verde Plantas com haste fina e grãos menores Começa nas folhas de baixo porque o potássio se move para as folhas novas. As margens amarelam e depois necrosam. Em casos fortes, a maturação atrasa e os grãos ficam enrugados.', array['Embrapa Soja — Tecnologias de produção de soja (edição vigente)']::text[], 'published', 48)
  on conflict (slug) do update set agent_type = excluded.agent_type, common_name = excluded.common_name, scientific_name = excluded.scientific_name,
    summary = excluded.summary, symptoms = excluded.symptoms, cause = excluded.cause, preventive_measures = excluded.preventive_measures,
    visual_cues = excluded.visual_cues, sources = excluded.sources, placeholder_hue = excluded.placeholder_hue;
