insert into treatments (problem_id, kind, text, active_ingredient, moa_group, agrofit_url, sort) select id, 'cultural', 'Corrigir com base na análise de solo e no histórico de produtividade. Use a calculadora do app como ponto de partida e confirme com um agrônomo.', null, null, null, 0 from problems where slug = 'deficiencia-de-potassio';
